import{_ as t,c as i,o,ae as a}from"./chunks/framework.Bw0Gm4PQ.js";const m=JSON.parse('{"title":"ADJUSTING IMPORTS OF AUTOMOBILES AND AUTOMOBILE","description":"","frontmatter":{"title":"ADJUSTING IMPORTS OF AUTOMOBILES AND AUTOMOBILE","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/adjusting-imports-of-automobiles-and-autombile-parts-into-the-united-states/","publishDate":"2025-03-26T18:53:33-04:00"},"headers":[],"relativePath":"executive-orders/2025-03-26-adjusting-imports-of-automobiles-and-automobile.md","filePath":"executive-orders/2025-03-26-adjusting-imports-of-automobiles-and-automobile.md"}'),r={name:"executive-orders/2025-03-26-adjusting-imports-of-automobiles-and-automobile.md"};function s(n,e,l,d,u,p){return o(),i("div",null,e[0]||(e[0]=[a('<h1 id="adjusting-imports-of-automobiles-and-automobile" tabindex="-1">ADJUSTING IMPORTS OF AUTOMOBILES AND AUTOMOBILE <a class="header-anchor" href="#adjusting-imports-of-automobiles-and-automobile" aria-label="Permalink to &quot;ADJUSTING IMPORTS OF AUTOMOBILES AND AUTOMOBILE&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/adjusting-imports-of-automobiles-and-autombile-parts-into-the-united-states/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/adjusting-imports-of-automobiles-and-autombile-parts-into-the-united-states/</a></p><p>Published: Wednesday, March 26, 2025</p><ul><li>On February 17, 2019, the Secretary of Commerce reported to the President that imports of automobiles and certain automobile parts threaten U.S. national security.</li><li>The President agreed with the Secretary&#39;s findings in Proclamation 9888 and directed negotiations with the European Union, Japan, and other countries; no agreements were reached.</li><li>The Secretary reported that national security concerns regarding automotive imports have escalated, worsened by COVID-19, exposing vulnerabilities in supply chains.</li><li>The President determined that tariffs are necessary to adjust imports of automobiles and parts to protect national security.</li><li>A 25% tariff will be imposed on specified automobiles and parts starting April 3, 2025, unless modified or terminated.</li><li>Importers of automobiles qualifying for USMCA may document U.S. content to potentially reduce tariff liability for non-U.S. content.</li><li>The 25% tariff may be retroactively applied if non-U.S. content value is inaccurately reported.</li><li>The tariff does not apply to USMCA-eligible automobile parts until a process for tariff application on non-U.S. content is established.</li><li>Includes a provision for the Secretary to modify the Harmonized Tariff Schedule (HTSUS) for implementing tariffs.</li><li>The Secretary will have 90 days to establish processes for including additional automobile parts for tariffs based on national security threats.</li><li>All imports must adhere to “privileged foreign status” in trade zones, if applicable.</li><li>The Secretary will continue monitoring imports and consulting on national security issues, reporting to the President as necessary.</li><li>No drawback on duties imposed by this proclamation; regulations and guidance may be issued as needed.</li><li>Previous inconsistent proclamations and Executive Orders are superseded by this proclamation.</li></ul>',4)]))}const f=t(r,[["render",s]]);export{m as __pageData,f as default};
